/**
 * @brief Velikost tabulky z80_meta_table v počtu záznamů.
 */
const size_t z80_meta_table_size =
    sizeof(z80_meta_table) / sizeof(z80_meta_table[0]);

/**
 * @brief Pomocná funkce pro lookup - používá ji z80_meta.c.
 *
 * Vrací NULL, pokud žádná entry neodpovídá.
 *
 * Algoritmus: prochází tabulku v pořadí, vrací první match, který:
 *   1. Souhlasí na (mnemonic, op1_type, op2_type)
 *   2. A souhlasí na subtype (= konkrétní hodnota nebo -1 wildcard)
 *
 * Konkrétní subtype má přednost před wildcard, protože speciální entries
 * (např. LD A,I) jsou v tabulce *před* obecnou (LD r,r').
 */
const z80_meta_t *z80_meta_table_lookup(
    const char *mnemonic,
    z80_operand_type_t op1_type, z80_operand_type_t op2_type,
    int op1_subtype_val, int op2_subtype_val)
{
    if (mnemonic == NULL) {
        return NULL;
    }
    /* Dvouprůchodový lookup:
     *  1. nejprve hledáme exact match (vč. subtype),
     *  2. potom fallback na wildcard subtype.
     * To zajistí, že LD A,I (subtype=I) má přednost před generic LD r,r'
     * (subtype=-1) i když by se obecná entry vešla také.
     */
    for (int pass = 0; pass < 2; pass++) {
        for (size_t i = 0; i < z80_meta_table_size; i++) {
            const z80_meta_entry_t *e = &z80_meta_table[i];
            if (e->op1_type != op1_type || e->op2_type != op2_type) {
                continue;
            }
            /* Mnemonika - statický string z dasm-z80 (sdílený buffer),
             * proto strcmp. */
            if (strcmp(e->mnemonic, mnemonic) != 0) {
                continue;
            }
            if (pass == 0) {
                /* První pass: hledáme entry se specifikovaným subtype,
                 * který sedí. Wildcardy (-1) povolíme, ale aspoň jeden
                 * z nich musí být specifický a sedět na vstupu. */
                int s1_ok = (e->op1_subtype < 0) ||
                            (e->op1_subtype == op1_subtype_val);
                int s2_ok = (e->op2_subtype < 0) ||
                            (e->op2_subtype == op2_subtype_val);
                int has_specific = (e->op1_subtype >= 0) ||
                                   (e->op2_subtype >= 0);
                if (s1_ok && s2_ok && has_specific) {
                    return &e->meta;
                }
            } else {
                /* Druhá pass: jen entries kde oba subtypes jsou wildcard. */
                if (e->op1_subtype < 0 && e->op2_subtype < 0) {
                    return &e->meta;
                }
            }
        }
    }
    /* Vstupy nepoužité proměnné: subtype hodnoty pro op1/op2 jsou v algoritmu
     * pokryty výše; následující voidy jsou jen na potlačení -Wunused-parameter
     * v případě, že by funkce byla zavolána s argumenty které nikam dál
     * neputují. */
    (void)op1_subtype_val;
    (void)op2_subtype_val;
    return NULL;
}

